def relation : Poly := X 0 * X 3 - X 2 * X 1 - 1
abbrev T := Poly ⧸ Ideal.span {relation}
def π : Poly →ₐ[ℂ] T := Ideal.Quotient.mkₐ ℂ _
def a : T := π (X 0)
def d : T := π (X 1)
def b : T := π (X 2)
def c : T := π (X 3)
def u : T := π (X 4)
def v : T := a ^ 3 * b - a ^ 2 * u ^ 3 - d ^ 2

/-- The defining equation of the five-variable hypersurface. -/
def relation (p s u F J : K) : K :=
  (quad p s u F) ^ 2 * F - (1 + 2 * s * quad p s u F) * J - p * J ^ 2 - u
